from html.parser import HTMLParser
class Validator(HTMLParser):
    def __init__(self):
        super().__init__()
        self.errors = []
        self.stack = []
        self.void_elements = {'area','base','br','col','embed','hr','img','input','link','meta','param','source','track','wbr'}
    def handle_starttag(self, tag, attrs):
        if tag not in self.void_elements:
            self.stack.append(tag)
    def handle_endtag(self, tag):
        if tag in self.void_elements:
            return
        if self.stack and self.stack[-1] == tag:
            self.stack.pop()
        elif tag in self.stack:
            while self.stack and self.stack[-1] != tag:
                self.errors.append(f'Mismatched close: </{tag}> with <{self.stack[-1]}> open')
                self.stack.pop()
            if self.stack:
                self.stack.pop()
        else:
            self.errors.append(f'Orphan close: </{tag}>')
with open('/app/output/final_report.html') as f:
    html = f.read()
v = Validator()
v.feed(html)
if v.errors:
    for e in v.errors: print(e)
elif v.stack:
    print(f'Unclosed tags: {v.stack}')
else:
    print('HTML structure valid - no unclosed tags or mismatches')
"

